    const minVersionMatch = code.match(
      /^\s*\/\*\s*@minVersion\s+(?<minVersion>\S+)\s*\*\/\s*$/m
    );
    if (!minVersionMatch) {
      throw new Error(`@minVersion number missing in ${filePath}`);
    }
    const { minVersion } = minVersionMatch.groups;

    if (isTs) {
      code = transformSync(code, {
        configFile: false,
        babelrc: false,
        filename: filePath,
        presets: [
          [
