        compress: { directives: false },
      })
    ).code;

    output += `\
  ${JSON.stringify(helperName)}: helper(
    ${JSON.stringify(minVersion)},
    ${JSON.stringify(code)},
  ),
`;
  }

  output += "});";
  return output;
}

